//! Byte-exact checks against vectors generated by google-auth and
//! google-cloud-storage (`tools/gen_vectors.py`) for a throwaway test key:
//! the service-account JWT assertion and V4 signed URLs.

use std::time::{Duration, UNIX_EPOCH};

use fsfast_core::{Options, Value};
use fsfast_gcs::auth::jwt::{ServiceAccountKey, parse_private_key};
use fsfast_gcs::sign::signed_url_v4;
use fsfast_gcs::{GCSFileSystem, GcsEnv};
use serde_json::Value as Json;

fn vectors() -> serde_json::Map<String, Json> {
    let text = include_str!("data/vectors.json");
    match serde_json::from_str(text).unwrap() {
        Json::Object(m) => m,
        _ => unreachable!(),
    }
}

fn key() -> ServiceAccountKey {
    let v = vectors();
    ServiceAccountKey::from_info(v["info"].as_object().unwrap()).unwrap()
}

#[test]
fn jwt_assertion_matches_google_auth() {
    let v = vectors();
    let k = key();
    let got = k
        .assertion(v["scope"].as_str().unwrap(), v["iat"].as_u64().unwrap())
        .unwrap();
    assert_eq!(got.as_str(), v["assertion"].as_str().unwrap());
}

#[test]
fn pkcs1_keys_sign_the_same() {
    let v = vectors();
    let pkcs1 = parse_private_key(v["pkcs1"].as_str().unwrap()).unwrap();
    let pkcs8 = parse_private_key(v["info"]["private_key"].as_str().unwrap()).unwrap();
    assert_eq!(pkcs1.public_modulus_len(), pkcs8.public_modulus_len());
    let mut info = v["info"].as_object().unwrap().clone();
    info.insert("private_key".into(), v["pkcs1"].clone());
    let k1 = ServiceAccountKey::from_info(&info).unwrap();
    assert_eq!(k1.sign(b"msg").unwrap(), key().sign(b"msg").unwrap());
}

#[test]
fn missing_fields_are_rejected() {
    let v = vectors();
    for field in ["client_email", "token_uri", "private_key"] {
        let mut info = v["info"].as_object().unwrap().clone();
        info.remove(field);
        let e = ServiceAccountKey::from_info(&info).unwrap_err();
        assert!(e.to_string().contains(field), "{e}");
    }
    let mut info = v["info"].as_object().unwrap().clone();
    info.insert("private_key".into(), Json::String("garbage".into()));
    assert!(ServiceAccountKey::from_info(&info).is_err());
}

#[test]
fn signed_urls_match_google_cloud_storage() {
    let v = vectors();
    let k = key();
    let now = UNIX_EPOCH + Duration::from_secs(v["iat"].as_u64().unwrap());
    let object = v["object"].as_str().unwrap();
    let url = signed_url_v4(&k, "https://storage.googleapis.com", "GET", "bucket-1", object, None, 3600, now).unwrap();
    assert_eq!(url, v["signed_url"].as_str().unwrap());
    let url = signed_url_v4(
        &k,
        "http://127.0.0.1:4443",
        "GET",
        "bucket-1",
        object,
        Some("1795547814877753"),
        900,
        now,
    )
    .unwrap();
    assert_eq!(url, v["signed_url_gen"].as_str().unwrap());
    assert!(signed_url_v4(&k, "https://storage.googleapis.com", "GET", "b", "o", None, 604_801, now).is_err());
}

#[test]
fn filesystem_signs_with_a_key_and_only_then() {
    let v = vectors();
    let mut opts = Options::new();
    let mut token = std::collections::BTreeMap::new();
    for (k, val) in v["info"].as_object().unwrap() {
        token.insert(k.clone(), Value::from(val.as_str().unwrap()));
    }
    opts.insert("token".into(), Value::Map(token));
    opts.insert("endpoint_url".into(), Value::from("https://storage.googleapis.com"));
    let fs = GCSFileSystem::from_options_with_env(opts, GcsEnv::from_pairs([("NO_GCE_CHECK", "true")])).unwrap();
    assert!(fsfast_core::FileSystem::capabilities(&fs).signed_urls);
    let now = UNIX_EPOCH + Duration::from_secs(v["iat"].as_u64().unwrap());
    let url = fs
        .sign_with(&format!("gs://bucket-1/{}", v["object"].as_str().unwrap()), "GET", Duration::from_secs(3600), now)
        .unwrap();
    assert_eq!(url, v["signed_url"].as_str().unwrap());
    assert_eq!(fs.auth_method(), "token");

    let mut opts = Options::new();
    opts.insert("token".into(), Value::from("anon"));
    let anon = GCSFileSystem::from_options_with_env(opts, GcsEnv::default()).unwrap();
    assert!(!fsfast_core::FileSystem::capabilities(&anon).signed_urls);
    let e = anon.sign_with("b/k", "GET", Duration::from_secs(1), now).unwrap_err();
    assert_eq!(e.kind(), fsfast_core::ErrorKind::Unsupported);
}
